-- How each session was signed in: `passkey`, `email-otp`, `github`, `device` or
-- `other`. Only a session a passkey signed in within the last ten minutes may
-- change how its account signs in; a session made before this column has no
-- method, and so never may. Generated by better-auth 1.7.7's compileMigrations
-- from the session's additionalFields, and held equal to them by [ba.schema].
-- Expand-only: a nullable column.
alter table "session" add column "signedInBy" text;
